1	import { ipcMain } from 'electron';
2	import { z } from 'zod';
3	import { parseArgs, parseArgsSafe, errorResponse } from './validate';
4	import { permissionModeSchema } from './schemas';
5	import {
6	  startDirectPty,
7	  startPty,
8	  startCommandPty,
9	  writePty,
10	  resizePty,
11	  killPty,
12	  killPtyAwait,
13	  killByOwner,
14	  sendRemoteControl,
15	  listForTask,
16	  setInitialPrompt,
17	  type PtyKind,
18	} from '../services/ptyManager';
19	import { DatabaseService } from '../services/DatabaseService';
20	import { terminalSnapshotService } from '../services/TerminalSnapshotService';
21	import { activityMonitor } from '../services/ActivityMonitor';
22	import { contextUsageService } from '../services/ContextUsageService';
23	import { remoteControlService } from '../services/remoteControlService';
24	import { TelemetryService } from '../services/TelemetryService';
25	import type { PermissionMode } from '@shared/types';
26	
27	export function registerPtyIpc(): void {
28	  ipcMain.handle(
29	    'pty:startDirect',
30	    async (
31	      event,
32	      args: {
33	        id: string;
34	        cwd: string;
35	        cols: number;
36	        rows: number;
37	        permissionMode?: PermissionMode;
38	        isDark?: boolean;
39	      },
40	    ) => {
41	      try {
42	        parseArgs(
43	          'pty:startDirect',
44	          z.looseObject({
45	            id: z.string(),
46	            cwd: z.string(),
47	            cols: z.number(),
48	            rows: z.number(),
49	            permissionMode: permissionModeSchema.optional(),
50	            isDark: z.boolean().optional(),
51	          }),
52	          args,
53	        );
54	        // The agent PTY id is the bare task id — look up its name and model so a
55	        // fresh spawn gets `claude --name <task>` (recognizable in /resume +
56	        // title) and `--model <alias>` (the user's per-task model choice). Read
57	        // from the DB here rather than threading through the renderer, since both
58	        // are stable task settings resolved at spawn time.
59	        const task = DatabaseService.getTask(args.id);
60	        const result = await startDirectPty({
61	          ...args,
62	          name: task?.name,
63	          model: task?.model,
64	          agentId: task?.agentId,
65	          agentProfile: task?.agentProfile,
66	          sender: event.sender,
67	        });
68	        TelemetryService.capture('terminal_started', { source: 'direct' });
69	        return { success: true, data: result };
70	      } catch (error) {
71	        return errorResponse(error);
72	      }
73	    },
74	  );
75	
76	  ipcMain.handle(
77	    'pty:start',
78	    async (event, args: { id: string; cwd: string; cols: number; rows: number }) => {
79	      try {
80	        parseArgs(
81	          'pty:start',
82	          z.looseObject({ id: z.string(), cwd: z.string(), cols: z.number(), rows: z.number() }),
83	          args,
84	        );
85	        const result = await startPty({
86	          ...args,
87	          sender: event.sender,
88	        });
89	        return { success: true, data: result };
90	      } catch (error) {
91	        return errorResponse(error);
92	      }
93	    },
94	  );
95	
96	  // Fire-and-forget channels (ipcMain.on instead of handle)
97	  ipcMain.on('pty:input', (_event, args: { id: string; data: string }) => {
98	    const v = parseArgsSafe('pty:input', z.looseObject({ id: z.string(), data: z.string() }), args);
99	    if (v === undefined) return;
100	    writePty(args.id, args.data);
101	  });
102	
103	  ipcMain.on('pty:resize', (_event, args: { id: string; cols: number; rows: number }) => {
104	    const v = parseArgsSafe(
105	      'pty:resize',
106	      z.looseObject({ id: z.string(), cols: z.number(), rows: z.number() }),
107	      args,
108	    );
109	    if (v === undefined) return;
110	    resizePty(args.id, args.cols, args.rows);
111	  });
112	
113	  ipcMain.on('pty:kill', (_event, id: string) => {
114	    const v = parseArgsSafe('pty:kill', z.string(), id);
115	    if (v === undefined) return;
116	    killPty(id);
117	  });
118	
119	  // Awaitable kill: resolves only after the child has exited (or the grace
120	  // window elapsed). The renderer awaits this before respawning so a fresh
121	  // `claude --resume` never races the dying process for the session jsonl.
122	  ipcMain.handle('pty:kill-await', async (_event, id: string) => {
123	    try {
124	      parseArgs('pty:kill-await', z.string(), id);
125	      await killPtyAwait(id);
126	      return { success: true };
127	    } catch (error) {
128	      return errorResponse(error);
129	    }
130	  });
131	
132	  // Snapshot handlers
133	  ipcMain.handle('pty:snapshot:get', async (_event, id: string) => {
134	    try {
135	      parseArgs('pty:snapshot:get', z.string(), id);
136	      const data = await terminalSnapshotService.getSnapshot(id);
137	      return { success: true, data };
138	    } catch (error) {
139	      return errorResponse(error);
140	    }
141	  });
142	
143	  ipcMain.on('pty:snapshot:save', (_event, id: string, payload: unknown) => {
144	    try {
145	      const v = parseArgsSafe('pty:snapshot:save', z.string(), id);
146	      if (v === undefined) return;
147	      void terminalSnapshotService.saveSnapshot(id, payload as any);
148	    } catch {
149	      // Best effort — fire-and-forget from beforeunload
150	    }
151	  });
152	
153	  ipcMain.handle('pty:snapshot:clear', async (_event, id: string) => {
154	    try {
155	      parseArgs('pty:snapshot:clear', z.string(), id);
156	      await terminalSnapshotService.deleteSnapshot(id);
157	      return { success: true };
158	    } catch (error) {
159	      return errorResponse(error);
160	    }
161	  });
162	
163	  // Store task context prompt in DB for SessionStart hook injection
164	  ipcMain.handle('pty:writeTaskContext', (_event, args: { taskId: string; prompt: string }) => {
165	    try {
166	      parseArgs(
167	        'pty:writeTaskContext',
168	        z.looseObject({ taskId: z.string(), prompt: z.string() }),
169	        args,
170	      );
171	      DatabaseService.setTaskContextPrompt(args.taskId, args.prompt);
172	      return { success: true };
173	    } catch (error) {
174	      return errorResponse(error);
175	    }
176	  });
177	
178	  // Stash the task's initial prompt so the first `claude` spawn auto-submits it
179	  // (positional arg, submitted once the trust gate clears) instead of injecting
180	  // it as silent SessionStart context the agent never acts on. One-shot: consumed
181	  // by the first startDirectPty for the task. Must be set before the terminal
182	  // mounts, which the renderer guarantees by awaiting this in createTask.
183	  ipcMain.handle('pty:setInitialPrompt', (_event, args: { taskId: string; prompt: string }) => {
184	    try {
185	      parseArgs(
186	        'pty:setInitialPrompt',
187	        z.looseObject({ taskId: z.string(), prompt: z.string() }),
188	        args,
189	      );
190	      setInitialPrompt(args.taskId, args.prompt);
191	      return { success: true };
192	    } catch (error) {
193	      return errorResponse(error);
194	    }
195	  });
196	
197	  // Activity monitor
198	  ipcMain.handle('pty:activity:getAll', () => {
199	    return { success: true, data: activityMonitor.getAll() };
200	  });
201	
202	  // Remote control
203	  ipcMain.handle('pty:remoteControl:enable', (_event, ptyId: string) => {
204	    try {
205	      parseArgs('pty:remoteControl:enable', z.string(), ptyId);
206	      sendRemoteControl(ptyId);
207	      return { success: true };
208	    } catch (error) {
209	      return errorResponse(error);
210	    }
211	  });
212	
213	  ipcMain.handle('pty:remoteControl:getAllStates', () => {
214	    return { success: true, data: remoteControlService.getAllStates() };
215	  });
216	
217	  // Status line data (context + cost + rate limits)
218	  ipcMain.handle('pty:statusLine:getAll', () => {
219	    return { success: true, data: contextUsageService.getAllStatusLine() };
220	  });
221	
222	  ipcMain.handle(
223	    'pty:listForTask',
224	    (_event, taskId: string, opts?: { kinds?: PtyKind[]; featureId?: string }) => {
225	      parseArgs('pty:listForTask', z.string(), taskId);
226	      parseArgs(
227	        'pty:listForTask',
228	        z
229	          .looseObject({
230	            kinds: z.array(z.enum(['agent', 'shell', 'tui', 'service'])).optional(),
231	            featureId: z.string().optional(),
232	          })
233	          .optional(),
234	        opts,
235	      );
236	      return { success: true, data: listForTask(taskId, opts) };
237	    },
238	  );
239	
240	  ipcMain.handle(
241	    'pty:startCommand',
242	    async (
243	      event,
244	      opts: {
245	        id: string;
246	        command: string;
247	        args: string[];
248	        cwd: string;
249	        cols: number;
250	        rows: number;
251	        env?: Record<string, string>;
252	        taskId: string;
253	        featureId: string;
254	      },
255	    ) => {
256	      try {
257	        parseArgs(
258	          'pty:startCommand',
259	          z.looseObject({
260	            id: z.string(),
261	            command: z.string(),
262	            args: z.array(z.string()),
263	            cwd: z.string(),
264	            cols: z.number(),
265	            rows: z.number(),
266	            env: z.record(z.string(), z.string()).optional(),
267	            taskId: z.string(),
268	            featureId: z.string(),
269	          }),
270	          opts,
271	        );
272	        const result = await startCommandPty({ ...opts, owner: event.sender });
273	        return { success: true, data: result };
274	      } catch (error) {
275	        return errorResponse(error);
276	      }
277	    },
278	  );
279	}
