1	import * as os from 'os';
2	import { type WebContents } from 'electron';
3	import { activityMonitor } from './ActivityMonitor';
4	import { hookServer } from './HookServer';
5	import { contextUsageService } from './ContextUsageService';
6	import { RtkService } from './RtkService';
7	import { WorkspacePortsRuntime } from './WorkspacePortsRuntime';
8	import { TerminalMirror } from './TerminalMirror';
9	import { terminalSnapshotService } from './TerminalSnapshotService';
10	import { ensureShellConfig } from './ptyShellConfig';
11	import { writeHookSettings, setCommitAttributionValue } from './ptyHookSettings';
12	// Import the registry and contract *directly*, never the ../agents barrel: the
13	// barrel imports the Claude adapter, which imports this module — going through
14	// it would form an import cycle. registry.ts / contract.ts depend on neither.
15	import { agentRegistry } from '../agents/registry';
16	import { DEFAULT_AGENT_ID } from '../agents/contract';
17	import type { PermissionMode, TaskModel } from '@shared/types';
18	
19	export type PtyKind = 'agent' | 'shell' | 'tui' | 'service';
20	
21	interface PtyRecord {
22	  proc: any; // IPty from node-pty
23	  cwd: string;
24	  isDirectSpawn: boolean;
25	  owner: WebContents | null;
26	  kind: PtyKind;
27	  taskId: string | null;
28	  featureId: string | null;
29	  /**
30	   * Headless xterm mirror fed every output chunk (the VS Code pty-host
31	   * pattern). Serialized on reattach so a fresh renderer xterm shows the
32	   * full terminal state — including output emitted while no renderer was
33	   * attached. Persisted to the snapshot files on kill/exit/quit.
34	   */
35	  mirror: TerminalMirror | null;
36	}
37	
38	const ptys = new Map<string, PtyRecord>();
39	
40	/** Persist a mirror's state to the snapshot files (sync — quit-safe). */
41	function persistMirrorSync(id: string, mirror: TerminalMirror): void {
42	  try {
43	    const data = mirror.serializeNow();
44	    if (!data) return;
45	    const { cols, rows } = mirror.dims();
46	    terminalSnapshotService
47	      .saveSnapshot(id, {
48	        version: 1,
49	        createdAt: new Date().toISOString(),
50	        cols,
51	        rows,
52	        data,
53	      })
54	      .catch(() => {
55	        // Persistence is best-effort (also: no `app` under test env).
56	      });
57	  } catch {
58	    // Persistence is best-effort.
59	  }
60	}
61	
62	/** Detach, persist, and dispose a record's mirror (kill/exit paths). */
63	function persistAndDisposeMirror(id: string, record: PtyRecord): void {
64	  const mirror = record.mirror;
65	  record.mirror = null;
66	  if (!mirror) return;
67	  // TUI tabs never restore from file snapshots (their side-car is torn down
68	  // and re-offered instead) — persisting would only leave orphan files.
69	  if (record.kind !== 'tui') persistMirrorSync(id, mirror);
70	  mirror.dispose();
71	}
72	
73	/** Serialize every live mirror to disk — before-quit + crash-resilience interval. */
74	export function persistAllMirrors(): void {
75	  for (const [id, record] of ptys) {
76	    if (record.kind === 'tui') continue;
77	    if (record.mirror) persistMirrorSync(id, record.mirror);
78	  }
79	}
80	
81	/**
82	 * Per-task initial prompt to pass as `claude`'s positional argument when the
83	 * task's agent PTY is spawned. Used by the ports onboarding migrate path:
84	 * the full inlined setup-prompt body (see PortsSetupPrompt) is stashed here
85	 * before the renderer triggers the spawn, so CC auto-submits it as soon as
86	 * the trust-this-directory gate clears — no post-spawn keystroke injection
87	 * needed (which previously raced first-run gates and flashed visibly in the
88	 * input box).
89	 *
90	 * Single-use: consumed (and removed) by startDirectPty's first spawn. A
91	 * re-attach to an existing PTY is a no-op — the prompt only applies to the
92	 * very first claude process for the task. Consequence: if that first spawn
93	 * dies before the user accepts the trust gate, the prompt is gone and a
94	 * respawn starts a plain session (the ports TUI then surfaces its
95	 * 30-minute timeout). The consumption breadcrumb in the ports debug log is
96	 * the trail for diagnosing that.
97	 */
98	const pendingInitialPrompts = new Map<string, string>();
99	
100	export function setInitialPrompt(taskId: string, prompt: string): void {
101	  pendingInitialPrompts.set(taskId, prompt);
102	}
103	
104	function consumeInitialPrompt(taskId: string): string | undefined {
105	  const prompt = pendingInitialPrompts.get(taskId);
106	  if (prompt !== undefined) pendingInitialPrompts.delete(taskId);
107	  return prompt;
108	}
109	
110	/** Test/cleanup hook: drop a stashed prompt without spawning. */
111	export function discardInitialPrompt(taskId: string): void {
112	  pendingInitialPrompts.delete(taskId);
113	}
114	
115	// Custom environment variables passed to spawned Claude processes (set from renderer settings).
116	let claudeEnvVars: Record<string, string> = {};
117	
118	// When true, inherit the full parent process.env as a base instead of the minimal set.
119	let syncShellEnv = false;
120	
121	// When true, launch Claude sessions in ultracode (X-High reasoning + multi-agent
122	// workflow orchestration) via `--settings '{"ultracode":true}'`. ultracode is
123	// session-only and can't be set through CLAUDE_CODE_EFFORT_LEVEL or --effort, so
124	// it's applied per-spawn here rather than through the effort env var.
125	let ultracode = false;
126	
127	const RESERVED_ENV_KEYS = new Set([
128	  'PATH',
129	  'HOME',
130	  'USER',
131	  'TERM',
132	  'COLORTERM',
133	  'TERM_PROGRAM',
134	  'COLORFGBG',
135	  // Dash owns this — it points hooks at the live HookServer port. A user/ports
136	  // override would misroute or break the no-op-outside-Dash guard.
137	  'DASH_HOOK_PORT',
138	]);
139	
140	export function setCommitAttribution(value: string | undefined): void {
141	  setCommitAttributionValue(value);
142	  refreshActivePtyHooks();
143	}
144	
145	export interface RefreshFailure {
146	  settingsPath: string;
147	  error: string;
148	}
149	
150	export interface RefreshResult {
151	  failures: RefreshFailure[];
152	}
153	
154	/**
155	 * Rewrite settings.local.json for every active PTY. Claude Code re-reads
156	 * settings per tool call, so this flips hooks live. Returns per-task write
157	 * failures so callers (RTK toggle, attribution change) can surface a
158	 * "saved, but N tasks didn't pick it up" message instead of silently
159	 * returning success.
160	 */
161	export function refreshActivePtyHooks(): RefreshResult {
162	  const failures: RefreshFailure[] = [];
163	  for (const [id, rec] of ptys) {
164	    // Shell PTYs (terminal drawer) share cwd with the task PTY but don't run
165	    // Claude Code and aren't tracked by ActivityMonitor. Writing hook settings
166	    // for them clobbers the task's settings.local.json with `ptyId=shell:…`,
167	    // so every subsequent hook event lands in ActivityMonitor's no-op branch
168	    // and the task's activity dot freezes on whatever it was last showing.
169	    if (!rec.isDirectSpawn) continue;
170	    const result = writeHookSettings(rec.cwd, id);
171	    if (!result.ok) {
172	      failures.push({ settingsPath: result.settingsPath, error: result.error });
173	    }
174	  }
175	  return { failures };
176	}
177	
178	export function setDesktopNotification(opts: { enabled: boolean }): void {
179	  hookServer.setDesktopNotification(opts);
180	}
181	
182	export function hasPty(id: string): boolean {
183	  return ptys.has(id);
184	}
185	
186	export function setClaudeEnvVars(vars: Record<string, string>): void {
187	  claudeEnvVars = vars;
188	}
189	
190	export function setSyncShellEnv(enabled: boolean): void {
191	  syncShellEnv = enabled;
192	}
193	
194	export function setUltracode(enabled: boolean): void {
195	  ultracode = enabled;
196	}
197	
198	// Lazy-load node-pty to avoid native binding issues at startup
199	let ptyModule: typeof import('node-pty') | null = null;
200	let ptyLoadError: string | null = null;
201	function getPty() {
202	  if (ptyLoadError) {
203	    throw new Error(ptyLoadError);
204	  }
205	  if (!ptyModule) {
206	    try {
207	      ptyModule = require('node-pty');
208	    } catch (err) {
209	      ptyLoadError =
210	        `[native module] node-pty failed to load: ${String(err)}. ` +
211	        'Try rebuilding native modules: pnpm rebuild';
212	      throw new Error(ptyLoadError);
213	    }
214	  }
215	  return ptyModule!;
216	}
217	
218	import { createBannerFilter } from './bannerFilter';
219	import { remoteControlService } from './remoteControlService';
220	
221	/**
222	 * Build environment for direct CLI spawn.
223	 * When syncShellEnv is off (default), uses a minimal set for fast, predictable spawns.
224	 * When on, inherits the full parent process.env as a base.
225	 *
226	 * Exported so the Claude agent adapter (src/main/agents/claude) can delegate to
227	 * the exact same env builder the host used pre-extraction — the shared spawn
228	 * environment (PATH merge, per-task port env, DASH_HOOK_PORT, auth passthrough)
229	 * is host infrastructure, and delegating keeps the Claude spawn byte-identical.
230	 */
231	export function buildDirectEnv(isDark: boolean, cwd?: string): Record<string, string> {
232	  const isWin = process.platform === 'win32';
233	  const base: Record<string, string> = syncShellEnv
234	    ? Object.fromEntries(Object.entries(process.env).filter((e): e is [string, string] => !!e[1]))
235	    : {};
236	
237	  // rtk's rewrite output invokes the bare name `rtk`; when the binary is
238	  // Dash-managed (userData/bin), prepend that dir so the rewrite resolves.
239	  const rtkBinDir = RtkService.getManagedBinDirForPath();
240	  const pathSep = isWin ? ';' : ':';
241	  const basePath = process.env.PATH || '';
242	  const mergedPath = rtkBinDir ? prependUnique(rtkBinDir, basePath, pathSep) : basePath;
243	
244	  const env: Record<string, string> = {
245	    ...base,
246	    TERM_PROGRAM: 'dash',
247	    HOME: os.homedir(),
248	    PATH: mergedPath,
249	    // Tell CLI apps about terminal background (rxvt convention)
250	    // Format: "fg;bg" where higher values = lighter colors
251	    COLORFGBG: isDark ? '15;0' : '0;15',
252	  };
253	
254	  if (isWin) {
255	    // Windows requires system env vars for DNS, credential storage, and Node.js.
256	    // Includes both casings of SystemRoot since some processes look for one or
257	    // the other (cmd.exe sets SystemRoot, PowerShell sees SYSTEMROOT in env).
258	    env.USERNAME = process.env.USERNAME || os.userInfo().username;
259	    const winVars = [
260	      'APPDATA',
261	      'LOCALAPPDATA',
262	      'USERPROFILE',
263	      'TEMP',
264	      'TMP',
265	      'SystemRoot',
266	      'SYSTEMROOT',
267	      'SystemDrive',
268	      'WINDIR',
269	      'COMSPEC',
270	      'PATHEXT',
271	      'COMPUTERNAME',
272	      'USERDOMAIN',
273	      'ProgramFiles',
274	    ];
275	    for (const key of winVars) {
276	      if (process.env[key]) env[key] = process.env[key]!;
277	    }
278	  } else {
279	    env.TERM = 'xterm-256color';
280	    env.COLORTERM = 'truecolor';
281	    env.USER = os.userInfo().username;
282	  }
283	
284	  if (!syncShellEnv) {
285	    // Auth passthrough — only needed when not inheriting full env
286	    const authVars = [
287	      'ANTHROPIC_API_KEY',
288	      'GH_TOKEN',
289	      'GITHUB_TOKEN',
290	      'HTTP_PROXY',
291	      'HTTPS_PROXY',
292	      'NO_PROXY',
293	      'http_proxy',
294	      'https_proxy',
295	      'no_proxy',
296	    ];
297	
298	    for (const key of authVars) {
299	      if (process.env[key]) {
300	        env[key] = process.env[key]!;
301	      }
302	    }
303	  }
304	
305	  // Merge user-configured environment variables from settings,
306	  // preventing overrides of internal keys that would break spawned processes.
307	  for (const [key, value] of Object.entries(claudeEnvVars)) {
308	    if (!RESERVED_ENV_KEYS.has(key)) {
309	      env[key] = value;
310	    }
311	  }
312	
313	  // Merge per-task port env vars (FRONTEND_PORT=…, etc) so commands run by
314	  // Claude resolve the same host port the user sees in the ports panel.
315	  // After user settings so a project never accidentally clobbers an allocated
316	  // port; before the CLAUDE_CODE_NO_FLICKER line so reserved-key checks above
317	  // would still apply if a user declared one in .dash/ports.json (the schema
318	  // enforces an allowlist regex; the RESERVED_ENV_KEYS list is a defense in
319	  // depth not really expected to fire here).
320	  if (cwd) {
321	    for (const [key, value] of Object.entries(WorkspacePortsRuntime.getEnvForWorktree(cwd))) {
322	      if (!RESERVED_ENV_KEYS.has(key)) env[key] = value;
323	    }
324	  }
325	
326	  // Disable Claude Code's built-in viewport scrolling — Dash uses its own terminal viewport
327	  env.CLAUDE_CODE_NO_FLICKER = '1';
328	
329	  // The HookServer port for this Dash session. ptyHookSettings writes hooks as
330	  // guarded curl commands that read $DASH_HOOK_PORT at runtime: present here →
331	  // they reach Dash; absent (a session the user launched outside Dash) → the
332	  // `[ -n … ]` guard makes them no-op instead of erroring with ECONNREFUSED.
333	  // Set last so it wins over any inherited value; only when the server is bound
334	  // (port 0 = not started — leaving the var unset keeps the guard honest).
335	  if (hookServer.port !== 0) {
336	    env.DASH_HOOK_PORT = String(hookServer.port);
337	  }
338	
339	  return env;
