358	/**
359	 * Build the `claude` CLI args. Pure so the resume/name/permission policy is
360	 * unit-testable without spawning. Two load-bearing rules:
361	 *  - `--resume <id>` and `--name` are mutually exclusive. `--name` is a
362	 *    fresh-session display label (shown in `/resume` + the terminal title);
363	 *    combining it with `--resume` is undocumented (rename? ignore? new
364	 *    session?), and resume already targets the right session by id.
365	 *  - the initial prompt, when present, is always the LAST positional — CC
366	 *    auto-submits it once the trust-this-directory gate clears.
367	 */
368	export function buildClaudeArgs(opts: {
369	  resumeSessionId: string | null;
370	  name?: string;
371	  permissionMode?: PermissionMode;
372	  /** Model alias (opus|sonnet|haiku|fable). 'default'/undefined → no --model. */
373	  model?: TaskModel;
374	  initialPrompt?: string;
375	}): string[] {
376	  const args: string[] = [];
377	  if (opts.resumeSessionId) {
378	    args.push('--resume', opts.resumeSessionId);
379	  } else if (opts.name) {
380	    args.push('--name', opts.name);
381	  }
382	  if (opts.permissionMode === 'acceptEdits') {
383	    args.push('--permission-mode', 'acceptEdits');
384	  } else if (opts.permissionMode === 'bypassPermissions') {
385	    args.push('--dangerously-skip-permissions');
386	  }
387	  // Pin the starting model when the user chose a non-default one. 'default' omits
388	  // the flag so the user's own Claude Code config decides. Orthogonal to
389	  // resume/name, so it applies to both fresh and resumed sessions.
390	  if (opts.model && opts.model !== 'default') {
391	    args.push('--model', opts.model);
392	  }
393	  // ultracode is session-scoped; re-apply on every spawn so the user's toggle
394	  // effectively sticks across the sessions Dash launches. Must precede the
395	  // positional prompt below.
396	  if (ultracode) {
397	    args.push('--settings', JSON.stringify({ ultracode: true }));
398	  }
399	  if (opts.initialPrompt) {
400	    args.push(opts.initialPrompt);
401	  }
402	  return args;
403	}
