765	/** Detach a record from all registries and persist its mirror (shared by the
766	 *  kill paths). The map delete makes the spawn-time onExit handler a no-op. */
767	function teardownRecord(id: string, record: PtyRecord): void {
768	  ptys.delete(id);
769	  activityMonitor.unregister(id);
770	  remoteControlService.unregister(id);
771	  contextUsageService.unregister(id);
772	  // Persist before killing — restart() relies on the snapshot for visual
773	  // context when it respawns into the same id.
774	  persistAndDisposeMirror(id, record);
775	}
